CREATE TABLE rm_consolidation_elimination_events (
 id INTEGER PRIMARY KEY CHECK(id > 0),
 elimination_id TEXT NOT NULL CHECK(length(elimination_id) BETWEEN 1 AND 64 AND substr(elimination_id,1,1) GLOB '[a-z]' AND elimination_id NOT GLOB '*[^a-z0-9-]*'),
 event_type TEXT NOT NULL CHECK(event_type IN ('proposed','approved','rejected','applied','reversed')),
 payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64 AND payload_hash NOT GLOB '*[^0-9a-f]*'),
 canonical_payload TEXT NOT NULL CHECK(length(canonical_payload) BETWEEN 2 AND 262144),
 previous_hash TEXT CHECK(previous_hash IS NULL OR (length(previous_hash)=64 AND previous_hash NOT GLOB '*[^0-9a-f]*')),
 event_hash TEXT NOT NULL UNIQUE CHECK(length(event_hash)=64 AND event_hash NOT GLOB '*[^0-9a-f]*'),
 actor TEXT NOT NULL CHECK(length(actor) BETWEEN 3 AND 160),
 created_at TEXT NOT NULL CHECK(length(created_at) BETWEEN 19 AND 30)
);
CREATE INDEX rm_consolidation_elimination_events_current_idx ON rm_consolidation_elimination_events(elimination_id,id DESC);
CREATE TRIGGER rm_consolidation_elimination_events_no_update BEFORE UPDATE ON rm_consolidation_elimination_events BEGIN SELECT RAISE(ABORT, 'consolidation elimination events are append-only'); END;
CREATE TRIGGER rm_consolidation_elimination_events_no_delete BEFORE DELETE ON rm_consolidation_elimination_events BEGIN SELECT RAISE(ABORT, 'consolidation elimination events are append-only'); END;
